.tox-editor-header {
  border: none !important;
}

.tox-collection__item-label code {
  color: #000 !important;
}
.tox-collection__item-label h1,
.tox-collection__item-label h2,
.tox-collection__item-label h3,
.tox-collection__item-label h4,
.tox-collection__item-label h5,
.tox-collection__item-label h6,
.tox-collection__item-label p,
.tox-collection__item-label div,
.tox-collection__item-label pre,
.tox-collection__item-label strong,
.tox-collection__item-label em,
.tox-collection__item-label span,
.tox-collection__item-label sup,
.tox-collection__item-label sub,
.tox-collection__item-label blockquote {
  color: #fff !important;
}

.tox-textarea {
  color: #000 !important;
  background-color: #fff !important;
  height: 100% !important;
}

.tox-textarea-wrap {
  height: 100% !important;
}

.tox-dialog-wrap__backdrop {
  background-color: transparent !important;
}

.tox-notification {
  color: #000 !important;
  fill: #000 !important;
}
.tox-notification * {
  color: currentColor !important;
  fill: currentColor !important;
}