  display: block;
  width: 100%;
  height: 2px;
  background-color: #ffffff;
  opacity: 0.8;
  background-size: 10px 10px;
  border-top: 1px dashed rgba(0, 39, 83, 0.5333333333);
  border-bottom: 1px dashed rgba(0, 39, 83, 0.1529411765);
}
.mce-content-body hr.wysiwyg-splitter.wysiwyg-spacer-0 {
  height: 2px;
}
.mce-content-body hr.wysiwyg-splitter.wysiwyg-spacer-s {
  background-image: repeating-linear-gradient(135deg, rgba(0, 39, 83, 0.1529411765) 0, rgba(0, 39, 83, 0.1529411765) 1px, #ffffff 0, #ffffff 50%);
  height: 15px;
}
.mce-content-body hr.wysiwyg-splitter.wysiwyg-spacer-m {
