:root {
  --wysiwyg-cols: 1;
  --wysiwyg-this-cols: 1;
  --wysiwyg-cols-last: 0;
}

.mce-content-body img {
  width: 100%;
  height: auto;
  box-sizing: border-box;
}

.mce-content-body img.wysiwyg-100 {
  width: 100%;
}

/* Responsive Images stuff */
.mce-content-body img:not(.wysiwyg-100).wysiwyg-right {
  float: right;
  padding-left: calc(-1 * (var(--wysiwyg-cols-last) - 1) * var(--wysiwyg-gutter));
}
.mce-content-body img:not(.wysiwyg-100).wysiwyg-left {
  float: left;
  padding-right: calc(-1 * (var(--wysiwyg-cols-last) - 1) * var(--wysiwyg-gutter));
}
.mce-content-body img:not(.wysiwyg-100).wysiwyg-16, .mce-content-body img:not(.wysiwyg-100).wysiwyg-33, .mce-content-body img:not(.wysiwyg-100).wysiwyg-66, .mce-content-body img:not(.wysiwyg-100).wysiwyg-12, .mce-content-body img:not(.wysiwyg-100).wysiwyg-25, .mce-content-body img:not(.wysiwyg-100).wysiwyg-50, .mce-content-body img:not(.wysiwyg-100).wysiwyg-75 {
  width: calc(-1 * (var(--wysiwyg-cols-last) - 1) * (100% / var(--wysiwyg-cols) + var(--wysiwyg-gutter) / var(--wysiwyg-cols)) * var(--wysiwyg-this-cols) + var(--wysiwyg-cols-last) * (100% / var(--wysiwyg-cols) * var(--wysiwyg-this-cols) - var(--wysiwyg-gutter) / var(--wysiwyg-cols) * (var(--wysiwyg-cols) - var(--wysiwyg-this-cols))));
}
.mce-content-body img:not(.wysiwyg-100).wysiwyg-16 {
  --wysiwyg-cols: 6;
}
.mce-content-body img:not(.wysiwyg-100).wysiwyg-33 {
  --wysiwyg-cols: 3;
}
.mce-content-body img:not(.wysiwyg-100).wysiwyg-66 {
  --wysiwyg-cols: 3;
  --wysiwyg-this-cols: 2;
}
