}
.mce-content-body {
  /* Content block */
}
.mce-content-body hr[sxc]::after {
  color: white;
  content: "App / Content";
  position: absolute;
  text-align: center;
  font-size: 25px;
  display: inline-block;
  /* 2px because of the border */
